import { test } from 'node:test';
import assert from 'node:assert/strict';
import { loadConfig } from '../config.js';
const defaults = { port: 3000, debug: false, name: 'app', maxRetries: 3, dbUrl: 'sqlite://x' };
test('defaults only', () => assert.deepEqual(loadConfig(defaults), defaults));
test('file on top', () => assert.deepEqual(loadConfig(defaults, { port: 8080, name: 'web' }), { ...defaults, port: 8080, name: 'web' }));
test('env on top, typed', () => {
  const env = { APP_PORT: '9000', APP_DEBUG: 'true', APP_MAX_RETRIES: '7', APP_DB_URL: 'pg://y', HOME: '/root' };
  assert.deepEqual(loadConfig(defaults, { port: 1 }, env), { port: 9000, debug: true, name: 'app', maxRetries: 7, dbUrl: 'pg://y' });
  assert.equal(loadConfig(defaults, {}, { APP_DEBUG: 'false' }).debug, false);
});
test('bad values throw', () => {
  assert.throws(() => loadConfig(defaults, {}, { APP_PORT: 'eighty' }), Error);
  assert.throws(() => loadConfig(defaults, {}, { APP_DEBUG: 'yes' }), Error);
  assert.throws(() => loadConfig(defaults, { colour: 'red' }), /colour/);
});
test('inputs untouched', () => {
  const d = { a: 1 }; const f = { a: 2 };
  const out = loadConfig(d, f, { APP_A: '3' });
  assert.deepEqual([d, f, out], [{ a: 1 }, { a: 2 }, { a: 3 }]);
});

