const snake = (k) => 'APP_' + k.replace(/([a-z0-9])([A-Z])/g, '$1_$2').toUpperCase();

function coerce(key, raw, example) {
  if (typeof example === 'number') {
    const n = Number(raw);
    if (Number.isNaN(n)) throw new Error(key + ' must be a number, got ' + raw);
    return n;
  }
  if (typeof example === 'boolean') {
    if (raw === 'true') return true;
    if (raw === 'false') return false;
    throw new Error(key + ' must be true or false, got ' + raw);
  }
  return raw;
}

export function loadConfig(defaults, file = {}, env = {}) {
  const out = { ...defaults };
  for (const [k, v] of Object.entries(file)) {
    if (!(k in defaults)) throw new Error('unknown config key: ' + k);
    out[k] = v;
  }
  for (const k of Object.keys(defaults)) {
    const name = snake(k);
    if (name in env) out[k] = coerce(k, env[name], defaults[k]);
  }
  return out;
}
